    "description": "AndroidManifest.xml source configuration",
    "content": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\">\n\n    <!-- Strictly offline: NO INTERNET permission requested -->\n    <!-- Local boot receiver for rescheduling WorkManager jobs -->\n    <uses-permission android:name=\"android.intent.action.BOOT_COMPLETED\" />\n    <uses-permission android:name=\"android.permission.RECEIVE_BOOT_COMPLETED\" />\n\n    <!-- Local Evening 9 PM notification permission (Android 13+) -->\n    <uses-permission android:name=\"android.permission.POST_NOTIFICATIONS\" />\n\n    <!-- Biometric / PIN Privacy Lock -->\n    <uses-permission android:name=\"android.permission.USE_BIOMETRIC\" />\n\n    <!-- Haptic vibration feedback -->\n    <uses-permission android:name=\"android.permission.VIBRATE\" />\n\n    <application\n        android:name=\".CigApp\"\n        android:allowBackup=\"false\"\n        android:dataExtractionRules=\"@xml/data_extraction_rules\"\n        android:fullBackupContent=\"@xml/backup_rules\"\n        android:icon=\"@mipmap/ic_launcher\"\n        android:label=\"@string/app_name\"\n        android:roundIcon=\"@mipmap/ic_launcher_round\"\n        android:supportsRtl=\"true\"\n        android:theme=\"@style/Theme.CigCounter\">\n\n        <!-- Main Application Activity -->\n        <activity\n            android:name=\".MainActivity\"\n            android:exported=\"true\"\n            android:windowSoftInputMode=\"adjustResize\"\n            android:theme=\"@style/Theme.CigCounter\">\n            <intent-filter>\n                <action android:name=\"android.intent.action.MAIN\" />\n                <category android:name=\"android.intent.category.LAUNCHER\" />\n            </intent-filter>\n        </activity>\n\n        <!-- Glance AppWidget Receiver -->\n        <receiver\n            android:name=\".widget.CigWidgetReceiver\"\n            android:exported=\"true\">\n            <intent-filter>\n                <action android:name=\"android.appwidget.action.APPWIDGET_UPDATE\" />\n            </intent-filter>\n            <meta-data\n                android:name=\"android.appwidget.provider\"\n                android:resource=\"@xml/widget_info\" />\n        </receiver>\n\n        <!-- Boot Completed Receiver to re-arm midnight & evening summary workers -->\n        <receiver\n            android:name=\".widget.BootReceiver\"\n            android:exported=\"false\">\n            <intent-filter>\n                <action android:name=\"android.intent.action.BOOT_COMPLETED\" />\n                <action android:name=\"android.intent.action.QUICKBOOT_POWERON\" />\n            </intent-filter>\n        </receiver>\n\n        <!-- FileProvider for sharing Damage Report PDFs -->\n        <provider\n            android:name=\"androidx.core.content.FileProvider\"\n            android:authorities=\"${applicationId}.fileprovider\"\n            android:exported=\"false\"\n            android:grantUriPermissions=\"true\">\n            <meta-data\n                android:name=\"android.support.FILE_PROVIDER_PATHS\"\n                android:resource=\"@xml/file_paths\" />\n        </provider>\n\n    </application>\n\n</manifest>\n"
