    "path": "app/src/main/java/com/cigcounter/app/data/AppDatabase.kt",
    "category": "kotlin",
    "description": "Room database configuration with automated schema migration",
    "content": "package com.cigcounter.app.data\n\nimport android.content.Context\nimport androidx.room.Database\nimport androidx.room.Room\nimport androidx.room.RoomDatabase\n\n@Database(\n    entities = [CigaretteLog::class],\n    version = 1,\n    exportSchema = false\n)\nabstract class AppDatabase : RoomDatabase() {\n\n    abstract fun cigaretteDao(): CigaretteDao\n\n    companion object {\n        @Volatile\n        private var INSTANCE: AppDatabase? = null\n\n        fun getInstance(context: Context): AppDatabase {\n            return INSTANCE ?: synchronized(this) {\n                INSTANCE ?: Room.databaseBuilder(\n                    context.applicationContext,\n                    AppDatabase::class.java,\n                    \"cig_counter_database\"\n                )\n                    .fallbackToDestructiveMigration()\n                    .build()\n                    .also { INSTANCE = it }\n            }\n        }\n    }\n}\n"
