    "description": "widget_preview.xml source configuration",
    "content": "<vector xmlns:android=\"http://schemas.android.com/apk/res/android\"\n    android:width=\"200dp\"\n    android:height=\"100dp\"\n    android:viewportWidth=\"200\"\n    android:viewportHeight=\"100\">\n    <!-- Rounded background container -->\n    <path\n        android:fillColor=\"#FF18181B\"\n        android:pathData=\"M16,0 H184 A16,16 0 0 1 200,16 V84 A16,16 0 0 1 184,100 H16 A16,16 0 0 1 0,84 V16 A16,16 0 0 1 16,0 Z\" />\n    <!-- Big round + button preview -->\n    <path\n        android:fillColor=\"#FFFF6E40\"\n        android:pathData=\"M42,50 m-28,0 a28,28 0 1,0 56,0 a28,28 0 1,0 -56,0\" />\n    <!-- Plus symbol inside button -->\n    <path\n        android:fillColor=\"#FFFFFFFF\"\n        android:pathData=\"M39,36h6v28h-6z\" />\n    <path\n        android:fillColor=\"#FFFFFFFF\"\n        android:pathData=\"M28,47h28v6h-28z\" />\n    <!-- Indicator lines for stats -->\n    <path\n        android:fillColor=\"#FF3F3F46\"\n        android:pathData=\"M84,24h100v8h-100z\" />\n    <path\n        android:fillColor=\"#FF3F3F46\"\n        android:pathData=\"M84,40h100v8h-100z\" />\n    <path\n        android:fillColor=\"#FF3F3F46\"\n        android:pathData=\"M84,56h100v8h-100z\" />\n    <path\n        android:fillColor=\"#FF27272A\"\n        android:pathData=\"M84,74h90v6h-90z\" />\n</vector>\n"
